	private String populatePlayerVsPlayers(int whichSide, String whatToProcess, MatchAllData matchAllData,
			int whichInning) {
		switch (config.getBroadcaster().toUpperCase()) {
		case Constants.NPL: case Constants.MPL: case Constants.APL:
			CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
					"$Select_GraphicsType*FUNCTION*Omo*vis_con SET 18\0", print_writers);
			switch (whatToProcess.split(",")[0]) {
			case "Control_Shift_E":
				CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
						"$Player_V_Player$Title$txt_Tittle1*GEOM*TEXT SET v BATTER\0", print_writers);
				for(BowlingCard bc : inning.getBowlingCard()) {
					if(bc.getPlayerId() == player.getPlayerId()) {
						
						switch (config.getBroadcaster().toUpperCase()) {
						case Constants.NPL: case Constants.APL:
							if(config.getPrimaryIpAddress().equalsIgnoreCase(Constants.LOCALHOST)) {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + "$Player_V_Player$ImageGrp$img_PlayerPhoto"
										+ "*TEXTURE*IMAGE SET "+(config.getBroadcaster().equalsIgnoreCase(Constants.APL)?Constants.APL_LOCAL_PHOTO_PATH:Constants.NPL_LOCAL_PHOTO_PATH)
										+ inning.getBowling_team().getTeamName4()+ "\\\\"+player.getPhoto()+CricketUtil.PNG_EXTENSION+"\0", print_writers);
							}else {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + "$Player_V_Player$ImageGrp$"
										+ "img_PlayerPhoto*TEXTURE*IMAGE SET "+"\\\\"+config.getPrimaryIpAddress()+(config.getBroadcaster().equalsIgnoreCase(Constants.APL) ? 
												Constants.APL_PHOTO_PATH:Constants.NPL_PHOTO_PATH)+ inning.getBowling_team().getTeamName4()+ "\\\\"+player.getPhoto()
												+CricketUtil.PNG_EXTENSION+"\0", print_writers);
								
							}
							break;
						case Constants.MPL:
							
							if(config.getCategory().equalsIgnoreCase("MEN")) {
								logoCategory = "M";
							}else if(config.getCategory().equalsIgnoreCase("WOMEN")) {
								logoCategory = "W";
							}else {
								logoCategory = "";
							}
							
							if(config.getPrimaryIpAddress().equalsIgnoreCase(Constants.LOCALHOST)) {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
										"$Player_V_Player$ImageGrp$img_PlayerPhoto*TEXTURE*IMAGE SET "+Constants.MPL_LOCAL_PHOTO_PATH+ inning.getBowling_team().getTeamBadge() + logoCategory + "\\\\"+player.getPhoto()+CricketUtil.PNG_EXTENSION+"\0", print_writers);
							}else {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
										"$Player_V_Player$ImageGrp$img_PlayerPhoto*TEXTURE*IMAGE SET "+"\\\\"+config.getPrimaryIpAddress()+Constants.MPL_PHOTO_PATH+ inning.getBowling_team().getTeamBadge() + logoCategory + "\\\\"+player.getPhoto()+CricketUtil.PNG_EXTENSION+"\0", print_writers);
								
							}
							break;	
						}
						
						CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
								"$Player_V_Player$ImageGrp$txt_Runs*GEOM*TEXT SET "+bc.getWickets()+"-"+bc.getRuns()+"\0", print_writers);
						CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
								"$Player_V_Player$ImageGrp$txt_Notout*ACTIVE SET 0\0", print_writers);
						CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
								"$Player_V_Player$ImageGrp$txt-Balls*GEOM*TEXT SET "+CricketFunctions.OverBalls(bc.getOvers(), bc.getBalls())+"\0", print_writers);
					}
				}
				break;

			case "Control_Shift_F":
				CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
						"$Player_V_Player$Title$txt_Tittle1*GEOM*TEXT SET v BOWLERS\0", print_writers);
				
				for(BattingCard bc : inning.getBattingCard()) {
					if(bc.getPlayerId() == player.getPlayerId()) {
						
						switch (config.getBroadcaster().toUpperCase()) {
						case Constants.NPL: case Constants.APL:
							if(config.getPrimaryIpAddress().equalsIgnoreCase(Constants.LOCALHOST)) {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + "$Player_V_Player$ImageGrp$img_PlayerPhoto"
										+ "*TEXTURE*IMAGE SET "+(config.getBroadcaster().equalsIgnoreCase(Constants.APL)?Constants.APL_LOCAL_PHOTO_PATH:Constants.NPL_LOCAL_PHOTO_PATH)
										+ inning.getBatting_team().getTeamName4()+ "\\\\"+player.getPhoto()+CricketUtil.PNG_EXTENSION+"\0", print_writers);
							}else {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + "$Player_V_Player$ImageGrp$img_PlayerPhoto"
										+ "*TEXTURE*IMAGE SET "+"\\\\"+config.getPrimaryIpAddress()+(config.getBroadcaster().equalsIgnoreCase(Constants.APL) ? 
												Constants.APL_PHOTO_PATH:Constants.NPL_PHOTO_PATH)+ inning.getBatting_team().getTeamName4()+ "\\\\"+player.getPhoto()
										+ CricketUtil.PNG_EXTENSION+"\0", print_writers);
							}
							break;
						case Constants.MPL:
							
							if(config.getCategory().equalsIgnoreCase("MEN")) {
								logoCategory = "M";
							}else if(config.getCategory().equalsIgnoreCase("WOMEN")) {
								logoCategory = "W";
							}else {
								logoCategory = "";
							}
							
							if(config.getPrimaryIpAddress().equalsIgnoreCase(Constants.LOCALHOST)) {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
										"$Player_V_Player$ImageGrp$img_PlayerPhoto*TEXTURE*IMAGE SET "+Constants.MPL_LOCAL_PHOTO_PATH+ inning.getBatting_team().getTeamBadge() + logoCategory + "\\\\"+player.getPhoto()+CricketUtil.PNG_EXTENSION+"\0", print_writers);
							}else {
								CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
										"$Player_V_Player$ImageGrp$img_PlayerPhoto*TEXTURE*IMAGE SET "+"\\\\"+config.getPrimaryIpAddress()+Constants.MPL_PHOTO_PATH+ inning.getBatting_team().getTeamBadge() + logoCategory + "\\\\"+player.getPhoto()+CricketUtil.PNG_EXTENSION+"\0", print_writers);
								
							}
							break;	
						}
						
						
						CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
								"$Player_V_Player$ImageGrp$txt_Runs*GEOM*TEXT SET "+bc.getRuns()+"\0", print_writers);
						if(bc.getStatus().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
							CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
									"$Player_V_Player$ImageGrp$txt_Notout*ACTIVE SET 1\0", print_writers);
						}else {
							CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
									"$Player_V_Player$ImageGrp$txt_Notout*ACTIVE SET 0\0", print_writers);
						}
						CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
								"$Player_V_Player$ImageGrp$txt-Balls*GEOM*TEXT SET "+bc.getBalls()+"\0", print_writers);
					}
				}
				break;
			}
			
			int maxRuns = 0, minBalls = 0;
			containerName = "";
			for(BestStats bs : batter_data) {
				if(bs.getRuns()>maxRuns) {
					maxRuns = bs.getRuns();
					minBalls = bs.getBalls();
				}else if(bs.getRuns() == maxRuns) {
					if(minBalls>bs.getBalls()) {
						minBalls = bs.getBalls();
					}
				}
			}
			rowId = 0;
			for(BestStats bs : batter_data) {
				rowId++;
				switch (config.getBroadcaster().toUpperCase()) {
				case Constants.NPL: case Constants.APL:
					if(bs.getRuns() == maxRuns && bs.getBalls() == minBalls) {
						omo = 1;
						containerName = "$Highlight";
					}else {
						omo = 0;
						containerName= "$Dehighlight";
					}
					break;
				case Constants.MPL:
					omo = 0;
					containerName= "$Dehighlight";
					break;

				}
				
				CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
						"$Player_V_Player$"+rowId+"$Select_Highlight*FUNCTION*Omo*vis_con SET "+omo+"\0", print_writers);
				CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
						"$Player_V_Player$"+rowId+"$Select_Highlight"+containerName+"$txt_Name*GEOM*TEXT SET "+bs.getPlayer().getFull_name()+"\0", print_writers);
				CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
						"$Player_V_Player$"+rowId+"$Select_Highlight"+containerName+"$txt_Runs*GEOM*TEXT SET "+bs.getRuns()+"\0", print_writers);
				CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
						"$Player_V_Player$"+rowId+"$Select_Highlight"+containerName+"$txt_Balls*GEOM*TEXT SET "+bs.getBalls()+"\0", print_writers);
				System.out.println("NAME : "+bs.getPlayer().getFull_name()+" : BALLS : "+bs.getBalls()+" : RUNS : "+bs.getRuns());
			}
			CricketFunctions.DoadWriteCommandToAllViz("-1 RENDERER*BACK_LAYER*TREE*$gfx_Full_Frame$AllGraphics$Side" + whichSide + 
					"$Player_V_Player$Select_PlayerNumber*FUNCTION*Grid*num_row SET "+rowId+"\0", print_writers);
			break;
		}
		return Constants.OK;
	}
